UIShrapnelImage=function(game,gameController){Phaser.Image.call(this,game,0,0,'game','mineShrapnel');this.gameController=gameController;this.anchor.setTo(0.5,0.5);this.scale.setTo(UIConstants.GAME_ASSET_SCALE,UIConstants.GAME_ASSET_SCALE);this.kill();};UIShrapnelImage.prototype=Object.create(Phaser.Image.prototype);UIShrapnelImage.prototype.constructor=UIShrapnelImage;UIShrapnelImage.prototype.update=function(){if(!this.exists){return;}this.rotation+=this.rotationSpeed*this.game.time.delta/1000;var projectile=this.gameController.getProjectile(this.projectileId);if(projectile){this.x=UIUtils.mpx(projectile.getX());this.y=UIUtils.mpx(projectile.getY());}};UIShrapnelImage.prototype.spawn=function(x,y,projectileId){this.reset(x,y);this.alpha=1.0;this.rotationSpeed=(Math.random()>0.5?1:-1)*(UIConstants.MINE_SHRAPNEL_MIN_ROTATION_SPEED+Math.random()*(UIConstants.MINE_SHRAPNEL_MAX_ROTATION_SPEED-UIConstants.MINE_SHRAPNEL_MIN_ROTATION_SPEED));this.projectileId=projectileId;};UIShrapnelImage.prototype.remove=function(){var projectile=this.gameController.getProjectile(this.projectileId);if(projectile){if(projectile.done()){this.rotationSpeed=0.0;this.fadeOutTween=this.game.add.tween(this).to({alpha:0.0},200,Phaser.Easing.Linear.None,true,0);this.fadeOutTween.onComplete.add(function(){this.kill();},this);}else{this.kill();}}else{this.kill();}};UIShrapnelImage.prototype.retire=function(){if(this.fadeOutTween){this.fadeOutTween.stop();}this.kill();};